INSERT INTO `soal` VALUES ('40','14','2','Rumus BEP dalam unit adalah ...<br>','1','Biaya tetap &divide; (Harga jual- Biaya variabel per unit)','Harga jual &divide; Biaya tetap','(Biaya variabel- Biaya tetap) &divide; Harga jual','Laba &divide; Biaya tetap','Total penjualan &divide; Total biaya','A',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('41','14','3','Jika biaya tetap Rp1.000.000, biaya variabel Rp10.000 per unit, dan harga jual Rp20.000 per unit, maka BEP-nya adalah ...? <br>','1','50 unit','100 unit','200 unit','500 unit','1000 unit','C',NULL,'','','','','','');
