INSERT INTO `soal` VALUES ('123','2','7','Sikap yang TIDAK mencerminkan cinta tanah air adalah...','1','Menebarkan berita bohong (hoax) yang dapat memecah belah bangsa.','Berpartisipasi dalam kegiatan sosial kemasyarakatan. ','Menghargai keberagaman budaya di Indonesia. ','Menjaga nama baik bangsa di mata dunia.','Mendukung produk dalam negeri. ','A',NULL,'','','','','','');
