INSERT INTO `soal` VALUES ('142','2','27','Di daerah-daerah tertentu sering terjadi sengketa yang disebabkan oleh harta warisan.  Penyebab utama terjadinya sengketa tersebut adalah...','1','Banyaknya ahli waris','Nilai harta yang besar','Kurangnya pemahaman tentang hukum waris','Adanya wasiat yang tidak jelas','Bukan dari ahli waris','C',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('143','2','28','Hadis yang menjelaskan tentang hak waris anak adalah...','1','Hadis tentang sabda Nabi SAW yang melarang wasiat lebih dari sepertiga harta.','Hadis tentang sabda Nabi SAW yang menganjurkan untuk berbuat baik kepada orang tua.','Hadis tentang sabda Nabi SAW yang menjelaskan tentang bagian ashabah.','Hadis tentang sabda Nabi SAW yang melarang menunda-nunda pembagian warisan.','Hadis tentang sabda Nabi SAW yang menjelaskan tentang bagian waris anak yatim.','E',NULL,'','','','','','');
