INSERT INTO `soal` VALUES ('145','2','30','<p>Pak Usman meninggal dunia meninggalkan harta sebesar Rp 240.000.000,-. Ahli warisnya terdiri dari seorang istri, ibu dan bapak, 1 anak laki-laki dan 2 anak perempuan. Jika bagian istri adalah 1/8, ibu 1/6 dan bapak 1/6, anak laki-laki dan anak perempuan akan menjadi ASHABAH, kemudian bagian anak laki-laki sebanyak dua kali anak perempuan, berapa bagian untuk anak laki-laki &hellip;</p>','1','Rp 65.000.000,-','Rp 32.500.000,-','Rp 30.000.000,-','Rp 45.500.000,-','Rp 25.000.000,-','A','','','','','','','');
INSERT INTO `soal` VALUES ('146','2','31','Yang tidak termasuk sebab-sebab seseorang mendapat harta warisan adalah&hellip;','1','Pertalian nasab','Pertalian budak','Pertalian pernikahan','Pertalian Agama','Pertalian Al-Wala&rsquo;','B',NULL,'','','','','','');
