INSERT INTO `soal` VALUES ('148','2','33','Bu Fatimah meninggal dunia dengan meninggalkan harta Rp. 35.000.000,-. Sementara ahli waris suami dan 4 saudara perempuan. Dalam pembagian harta warisan, suami mendapatkan &frac12; dari harta dan 4 saudara perempuan mendapatkan 2/3. Melihat keadaan dari ahli waris, maka penghitungannya harus secara &lsquo;AUL. maka suami memperoleh harta sebanyak&hellip;.','1','Rp. 10.000.000,-','Rp. 15.000.000,-','Rp. 20.000.000,-','Rp. 25.000.000,-','Rp. 30.000.000,-','C',NULL,'','','','','','');
