INSERT INTO `soal` VALUES ('439','3','23','Sikap tidak mematuhi rambu lalu lintas dan mengabaikan keselamatan pengguna jalan lain meru- <br> pakan  bentuk ....','1','Pelanggaran hak asasi manusia ','Pengingkaran kewajiban warga Negara ','Tidak ada hubungannya dengan hak dan kewajiban ','Sikap yang dijamin oleh kebebasan pribadi ','Pelaksanaan kewajiban warga Negara','B',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('440','3','24','Hak setiap orang untuk memeluk agama dan beribadat menurut agamanya diatur dalam UUD NRI <br> Tahun 1945 Pasal ....','1','28E ayat (2)','29 ayat (1)','30 ayat (1)','31 ayat (1)','33 ayat (3)','E',NULL,'','','','','','');
