INSERT INTO `soal` VALUES ('444','3','28','Sebuah kampanye yang efektif untuk meningkatkan kesadaran akan hak dan kewajiban seharusnya <br>  memiliki pesan yang .... ','1','Rumit dan penuh jargon hukum ','Positif, mudah dipahami, dan persuasive','Hanya berisi larangan dan ancaman ','Ditujukan hanya untuk kelompok tertentu ','Berisi himbauan ','B',NULL,'','','','','','');
