INSERT INTO `soal` VALUES ('446','3','30','Untuk mencegah terjadinya tawuran antar pelajar, beberapa siswa dari sekolah berbeda berinisiatif <br>  membentuk forum diskusi dan mengadakan kegiatan olahraga bersama. Upaya ini paling tepat <br>  mencerminkan sifat &#39;Warga Negara yang ASIK&#39; pada huruf .... ','1','Aktif ','Solutif ','Inisiatif ','Kolaboratif ','Efektif','D',NULL,'','','','','','');
