INSERT INTO `soal` VALUES ('450','3','34','Sebagai &quot;Generasi Solutif,&quot; peran paling dasar yang harus dilakukan oleh seorang pelajar dalam mengatasi <br> masalah pelanggaran hak dan pengingkaran kewajiban adalah &hellip;.','1','Mengkritik pemerintah di media sosial ','Mengorganisir demonstrasi besar ','Memahami dan melaksanakan hak serta kewajiban di lingkungan terdekat ','Membuat laporan polisi untuk setiap pelanggaran kecil ','Menuntut hak tanpa peduli kewajiban orang lain ','C',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('451','3','35','Menjaga keseimbangan antara hak dan kewajiban merupakan salah satu perwujudan sikap yang sesuai dengan <br> nilai Pancasila, khususnya pada sila ke .&hellip; ','1','1','2','3','4','5','E',NULL,'','','','','','');
