INSERT INTO `soal` VALUES ('453','3','37','Seorang siswa yang sering datang terlambat ke sekolah, secara tidak langsung, telah melanggar hak guru dan <br> siswa lainnya. Pelanggaran ini terjadi karena adanya ....','1','Pelanggaran HAM ','Pengingkaran kewajiban siswa ','Ketidakadilan ','Diskriminasi ','Pelanggaran sosial ','B',NULL,'','','','','','');
