INSERT INTO `soal` VALUES ('455','3','39','Setelah mengidentifikasi masalah intoleransi, para siswa mulai membuat sebuah video pendek yang akan <br> diunggah ke media sosial. Tindakan ini termasuk dalam tahapan ....','1','Rancang ','Bangun ','Menerapkan ','Kolaborasi ','Promosi ','B',NULL,'','','','','','');
