INSERT INTO `soal` VALUES ('728','12','21','Apa perbedaan utama antara metode FIFO dan LIFO dalam penilaian persediaan?','1','FIFO menjual barang terakhir yang masuk terlebih dahulu, sedangkan LIFO menjual yang pertama','FIFO dan LIFO menggunakan harga rata-rata untuk menentukan nilai persediaan','FIFO menjual barang yang pertama kali masuk terlebih dahulu, sedangkan LIFO menjual yang terakhir kali masuk terlebih dahulu','FIFO lebih cocok saat harga menurun, sedangkan LIFO cocok saat harga tetap','LIFO digunakan untuk mencatat barang yang tidak dapat rusak','C',NULL,'','','','','','');
